import Foundation
import CryptoKit

/// streetzim-recipe/2: no ZIM rewriting is performed on the device.
/// Only verified source ranges and generated bytes are copied, in order.
struct StreetZimRecipe: Decodable, Sendable {
    let format: String
    let uuid: String
    let name: String
    let fileName: String?
    let size: Int64
    let md5: String
    let fileMD5: String?
    let base: Source
    let packs: [String: Source]
    let segments: [Segment]

    enum CodingKeys: String, CodingKey {
        case format, uuid, name, size, md5, base, packs, segments
        case fileName = "file_name"
        case fileMD5 = "file_md5"
    }

    struct Source: Decodable, Sendable {
        let file: String
        let size: Int64
        let uuid: String
        let chunk: Int64
        let sha256: [String]
        let mask: [[Int64]]?
        let url: String?

        func validate() throws {
            guard size > 0, chunk > 0, chunk <= 16 * 1024 * 1024,
                  sha256.count == (size - 1) / chunk + 1,
                  sha256.allSatisfy({ StreetZimRecipe.isHex($0, count: 64) }),
                  UUID(uuidString: normalizedUUID) != nil else { throw StreetZimError.invalidRecipe }
            for range in mask ?? [] {
                guard range.count == 2, range[0] >= 0, range[1] >= 0,
                      range[0] <= size, range[1] <= size - range[0] else {
                    throw StreetZimError.invalidRecipe
                }
            }
        }

        var normalizedUUID: String {
            let hex = uuid.replacingOccurrences(of: "-", with: "")
            guard hex.count == 32 else { return "" }
            let chars = Array(hex)
            return [chars[0..<8], chars[8..<12], chars[12..<16], chars[16..<20], chars[20..<32]]
                .map { String($0) }.joined(separator: "-")
        }

        func masked(_ data: Data, at offset: Int64) -> Data {
            var result = data
            for range in mask ?? [] {
                let lower = max(range[0], offset)
                let upper = min(range[0] + range[1], offset + Int64(data.count))
                if lower < upper {
                    result.resetBytes(in: Int(lower - offset)..<Int(upper - offset))
                }
            }
            return result
        }
    }

    struct Segment: Decodable, Sendable {
        let src: String
        let pack: String?
        let off: Int64?
        let len: Int64?
        let data: String?
        let sha256: String?
    }

    var outputName: String { (fileName ?? name) + ".zim" }

    func validate() throws {
        guard format == "streetzim-recipe/2", UUID(uuidString: uuid) != nil,
              Self.isHex(md5, count: 32), fileMD5.map({ Self.isHex($0, count: 32) }) ?? true,
              size > 16, !segments.isEmpty, segments.last?.src == "md5",
              !outputName.contains("/"), !outputName.contains("\\"),
              !outputName.hasPrefix("."), outputName.utf8.count <= 240 else {
            throw StreetZimError.invalidRecipe
        }
        try base.validate()
        for source in packs.values { try source.validate() }
        var total: Int64 = 0
        for (index, segment) in segments.enumerated() {
            let length: Int64
            switch segment.src {
            case "md5":
                guard index == segments.count - 1 else { throw StreetZimError.invalidRecipe }
                length = 16
            case "inline":
                guard let encoded = segment.data, let bytes = Data(base64Encoded: encoded),
                      let len = segment.len, Int64(bytes.count) == len,
                      let expected = segment.sha256, Self.sha256(bytes) == expected else {
                    throw StreetZimError.integrity
                }
                length = len
            case "base", "pack":
                let source = segment.src == "base" ? base : packs[segment.pack ?? ""]
                guard let source, let off = segment.off, let len = segment.len,
                      off >= 0, len >= 0, off <= source.size, len <= source.size - off,
                      !(source.mask ?? []).contains(where: { off < $0[0] + $0[1] && $0[0] < off + len }) else {
                    throw StreetZimError.invalidRecipe
                }
                length = len
            default: throw StreetZimError.invalidRecipe
            }
            guard length <= size - total else { throw StreetZimError.invalidRecipe }
            total += length
        }
        guard total == size else { throw StreetZimError.invalidRecipe }
    }

    static func sha256(_ bytes: Data) -> String { hex(SHA256.hash(data: bytes)) }
    static func hex<S: Sequence>(_ bytes: S) -> String where S.Element == UInt8 {
        bytes.map { String(format: "%02x", $0) }.joined()
    }
    static func isHex(_ string: String, count: Int) -> Bool {
        string.utf8.count == count && string.utf8.allSatisfy { (48...57).contains($0) || (97...102).contains($0) }
    }
}
